/**
 * @file cachecliff.h
 * @brief Find where the cache and memory system of a CPU starts to hurt.
 *
 * The program calls functions from a bank of generated callbacks through a
 * table, picking them at random, and times it. How many functions it picks
 * from (the code footprint), how skewed the choice is, and how big the data
 * region the callbacks read and write is (the data footprint), are run-time
 * parameters: one build sweeps them all.
 *
 * The bank is generated by tools/ccgen.py and committed under bank/, so a
 * build needs nothing but a C99 compiler.
 *
 * @copyright SPDX-License-Identifier: MIT
 */
#ifndef CACHECLIFF_H
#define CACHECLIFF_H

#include <stddef.h>
#include <stdint.h>

/** @brief Version of cachecliff. */
#define CC_VERSION "0.1.0"

/**
 * @defgroup cc_config Build-time capacity
 * @brief How much to link in, so that the program fits the target.
 *
 * What is actually used is chosen at run time. Override the macros on the
 * compiler command line, e.g. <tt>-DCC_NFUNCS=256 -DCC_DATA_BYTES=65536</tt>.
 * @{
 */

/**
 * @brief Callbacks linked in.
 *
 * A power of two, at least 64, at most the size of the generated bank
 * (<tt>ccgen.py --funcs</tt>). One function is 100 to 400 bytes of code.
 */
#ifndef CC_NFUNCS
#define CC_NFUNCS 1024
#endif

/**
 * @brief Size of the data region the callbacks read and write, in bytes.
 *
 * A power of two, at least 1024.
 */
#ifndef CC_DATA_BYTES
#define CC_DATA_BYTES (1024u * 1024u)
#endif

/**
 * @brief Attributes of every callback.
 *
 * The default keeps the compiler from inlining them. Define it to put the bank
 * in another memory, e.g. <tt>__attribute__((section(".ramfunc"), noinline))</tt>.
 */
#ifndef CC_FN_ATTR
#if defined(__GNUC__) || defined(__clang__)
#define CC_FN_ATTR __attribute__((noinline))
#else
#define CC_FN_ATTR
#endif
#endif

/**
 * @brief Attributes of the data region.
 *
 * The default aligns it to a cache line pair. Define it to put the region in
 * another memory, e.g. <tt>__attribute__((section(".axi_bss"), aligned(64)))</tt>.
 */
#ifndef CC_DATA_ATTR
#if defined(__GNUC__) || defined(__clang__)
#define CC_DATA_ATTR __attribute__((aligned(64)))
#else
#define CC_DATA_ATTR
#endif
#endif

/**
 * @brief Most calls (or loads) of the pilot run that finds how many calls a
 *        measurement needs.
 *
 * The pilot runs 256, 1024, ... calls until it is long enough to read on the
 * timer; this is where it gives up, for a timer that does not advance.
 */
#ifndef CC_PILOT_MAX_CALLS
#define CC_PILOT_MAX_CALLS (1u << 26)
#endif

/** @brief Least time one measurement takes, in milliseconds. */
#ifndef CC_TARGET_MS
#define CC_TARGET_MS 20u
#endif

/** @} */

#if (CC_NFUNCS < 64) || ((CC_NFUNCS & (CC_NFUNCS - 1)) != 0)
#error "CC_NFUNCS must be a power of two and at least 64"
#endif
#if (CC_DATA_BYTES < 1024u) || ((CC_DATA_BYTES & (CC_DATA_BYTES - 1)) != 0)
#error "CC_DATA_BYTES must be a power of two and at least 1024"
#endif

/**
 * @defgroup cc_callbacks Callbacks
 * @brief The generated functions and the table that points to them.
 * @{
 */

/** @brief What a callback gets besides its value: the data region. */
typedef struct cc_ctx {
    uint32_t *data; /**< The data region. */
    uint32_t mask; /**< Number of 32-bit words in the part in use, minus one. */
} cc_ctx;

/**
 * @brief Signature of a callback.
 * @param[in] x Value passed from one callback to the next.
 * @param[in] c The data region.
 * @return The new value.
 */
typedef uint32_t (*cc_fn)(uint32_t x, cc_ctx *c);

/**
 * @brief Declares a callback.
 * @param name Name of the function.
 */
#define CC_FN_DECL(name) uint32_t name(uint32_t x, cc_ctx *c)

/**
 * @brief Defines a callback, with CC_FN_ATTR.
 * @param name Name of the function.
 */
#define CC_FN(name) CC_FN_ATTR uint32_t name(uint32_t x, cc_ctx *c)

/** @brief The callbacks, in the order of their addresses (bank/cc_table.c). */
extern const cc_fn cc_table[CC_NFUNCS];

/** @brief Fingerprint of the generated sources, to tell banks apart. */
extern const uint32_t cc_bank_id;

/** @brief Functions the bank was generated with; at least CC_NFUNCS. */
extern const uint32_t cc_bank_nfuncs;

/**
 * @brief What calling every one of the first 64, 128, ... callbacks once must
 *        return.
 *
 * Computed by tools/ccgen.py with its own implementation of the statements.
 * Entry k is for 64 << k functions. See cc_validate().
 */
extern const uint32_t cc_validate_all[];

/** @brief What 2000 random calls among the first 64 callbacks must return. */
extern const uint32_t cc_validate_draw;

/** @} */

/**
 * @defgroup cc_engine Engine
 * @brief The dispatcher and the timing.
 * @{
 */

/** @brief What to run: how many callbacks, how to pick them, how much data. */
typedef struct cc_cfg {
    uint32_t nfuncs; /**< Callbacks to pick from: the first nfuncs of cc_table. */
    uint32_t skew; /**< 1: uniform. k: the smallest of k draws (low numbers are hot). */
    uint32_t period; /**< The sequence of calls repeats every period calls; 0: never. */
    uint32_t data_bytes; /**< Part of the data region the callbacks use. */
} cc_cfg;

/** @brief The outcome of cc_measure(). */
typedef struct cc_result {
    uint32_t ticks; /**< Time of the timed run, in port ticks. */
    uint32_t calls; /**< Callbacks called in that run. */
    uint32_t sink; /**< The value the callbacks computed; it keeps them alive. */
} cc_result;

/**
 * @brief One step of the xorshift32 generator.
 * @param[in] s State, not zero.
 * @return The next state.
 */
uint32_t cc_xorshift(uint32_t s);

/**
 * @brief One draw of the dispatcher.
 *
 * Draws the index of the next callback. With skew 1 it is uniform over
 * <tt>[0, n)</tt>; with skew k it is the smallest of k uniform draws, so the
 * low indices are called more often.
 *
 * @param[in,out] state Generator state; advanced by skew steps.
 * @param[in] n Number of callbacks to pick from.
 * @param[in] skew See cc_cfg::skew. 0 is taken as 1.
 * @return An index in <tt>[0, n)</tt>.
 */
uint32_t cc_draw(uint32_t *state, uint32_t n, uint32_t skew);

/**
 * @brief Fills the data region with pseudo-random words.
 * @param[out] d First word.
 * @param[in] words Number of words.
 * @param[in] seed Seed of the generator.
 */
void cc_data_fill(uint32_t *d, uint32_t words, uint32_t seed);

/**
 * @brief The data region.
 * @return Its first word; CC_DATA_BYTES long.
 */
uint32_t *cc_data(void);

/**
 * @brief Sets the least time a measurement takes.
 * @param[in] ms Milliseconds; 0 is taken as 1. The default is CC_TARGET_MS.
 */
void cc_set_target_ms(uint32_t ms);

/**
 * @brief Calls callbacks, chosen by the dispatcher.
 * @param[in] cfg What to run.
 * @param[in] calls How many callbacks to call.
 * @param[in] seed Seed of the dispatcher. The same seed gives the same calls.
 * @param[in] x0 First value passed to a callback.
 * @return The value the last callback returned.
 */
uint32_t cc_run(const cc_cfg *cfg, uint32_t calls, uint32_t seed, uint32_t x0);

/**
 * @brief The number of calls (or steps) that takes a given time.
 * @param[in] calls Calls of a run that was timed.
 * @param[in] ticks Ticks that run took; 0 is taken as "too short to see".
 * @param[in] target Ticks wanted.
 * @return Calls for @p target ticks, between 256 and 2^28.
 */
uint32_t cc_scale_calls(uint32_t calls, uint32_t ticks, uint32_t target);

/**
 * @brief The median of three values.
 * @param[in,out] a The values; sorted on return, so a[1] is the median.
 */
void cc_median3(uint32_t *a);

/**
 * @brief Times a configuration.
 *
 * Finds the number of calls that takes about CC_TARGET_MS, warms up, then
 * times three runs and takes the median.
 *
 * @param[in] cfg What to run.
 * @return Ticks and calls of the median run.
 */
cc_result cc_measure(const cc_cfg *cfg);

/**
 * @brief Follows pointers through the data region.
 *
 * Every load needs the result of the one before, so nothing overlaps. The
 * region must have been built by cc_chase_ticks_per_load_x1000(), which is the
 * function to call for a measurement.
 *
 * @param[in] steps Number of loads.
 * @param[out] sink Where the walk ended; keeps the loads alive.
 * @return Ticks the loads took.
 */
uint32_t cc_chase(uint32_t steps, uint32_t *sink);

/**
 * @brief Time of one dependent load from a region of a given size.
 *
 * Builds a random cycle through <tt>bytes / 64</tt> nodes of one cache line
 * each, and walks it.
 *
 * @param[in] bytes Size of the region, at most CC_DATA_BYTES.
 * @return Ticks per load, times 1000.
 */
uint32_t cc_chase_ticks_per_load_x1000(uint32_t bytes);

/**
 * @brief Checks callbacks against the values tools/ccgen.py computed.
 *
 * cc_validate() calls it with the bank that is linked in; a test can pass
 * values that are wrong on purpose.
 *
 * @param[in] table The callbacks.
 * @param[in] nfuncs Their number: a power of two, at least 64.
 * @param[in] bank_nfuncs Functions the bank was generated with.
 * @param[in] expect_all What calling the first 64, 128, ... callbacks once returns.
 * @param[in] expect_draw What 2000 random calls among the first 64 return.
 * @return The number of mismatches; 0 if all is well. 1000 if the table is
 *         bigger than the bank.
 */
int cc_validate_with(const cc_fn *table, uint32_t nfuncs, uint32_t bank_nfuncs,
    const uint32_t *expect_all, uint32_t expect_draw);

/**
 * @brief Checks the callbacks of the bank that is linked in.
 * @return The number of mismatches; 0 if all is well.
 */
int cc_validate(void);

/** @} */

/**
 * @defgroup cc_port Port
 * @brief What a platform provides: a timer and an output.
 *
 * See port/posix/cc_port.c for an example.
 * @{
 */

/** @brief Called once, before anything else: set up the timer and the output. */
void cc_port_init(void);

/**
 * @brief The timer.
 * @return A free-running counter that wraps at 2^32. The engine measures an
 *         interval as a difference, and keeps each interval below 2^31 ticks.
 */
uint32_t cc_port_ticks(void);

/**
 * @brief The rate of the timer.
 * @return Ticks per second.
 */
uint32_t cc_port_ticks_per_sec(void);

/**
 * @brief The output.
 * @param[in] s A zero-terminated string, printed as it is.
 */
void cc_port_puts(const char *s);

/** @} */

/**
 * @defgroup cc_report Report
 * @brief The sweeps and the text they print.
 * @{
 */

/**
 * @brief The part of the code the first n callbacks occupy.
 *
 * The callbacks are generated in the order of their addresses, so the span is
 * the distance from the first to the next one after the n-th. Past the last
 * one it is extrapolated from the average. A toolchain that reorders the
 * functions makes it meaningless.
 *
 * @param[in] table The callbacks.
 * @param[in] total Their number.
 * @param[in] n How many of them, at least 2.
 * @return The span in bytes, or 0 if the layout is not as expected.
 */
uint32_t cc_code_span(const cc_fn *table, uint32_t total, uint32_t n);

/**
 * @brief Prints a size in KiB with one decimal.
 * @param[out] buf At least 16 bytes.
 * @param[in] bytes The size; 0 is printed as "?" (an unknown size).
 */
void cc_fmt_kib(char *buf, uint32_t bytes);

/** @brief What cc_main() does. */
typedef struct cc_options {
    int csv; /**< Print machine-readable lines instead of tables. */
    int quick; /**< A shorter sweep: a quarter of the time per point. */
    int validate_only; /**< Only check the callbacks. */
} cc_options;

/**
 * @brief Runs the sweeps and prints the report.
 * @param[in] opt Options.
 * @return 0 if the callbacks passed the validation, 1 if not.
 */
int cc_main(const cc_options *opt);

/** @} */

#endif /* CACHECLIFF_H */
